import{_ as o,o as c,c as d,a2 as p}from"./chunks/framework.Bg-Zxr5O.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Syntax.md","filePath":"manual-zh/Syntax.md","lastUpdated":1785684581000}'),a={name:"manual-zh/Syntax.md"};function E(t,e,S,n,I,R){return c(),d("div",null,[...e[0]||(e[0]=[p(`<h4 id="_15-17-1-语法" tabindex="-1">15.17.1 语法 <a class="header-anchor" href="#_15-17-1-语法" aria-label="Permalink to &quot;15.17.1 语法&quot;">​</a></h4><pre><code>REGRESSION
        /VARIABLES=var_list
        /DEPENDENT=var_list
        /STATISTICS={ALL, DEFAULTS, R, COEFF, ANOVA, BCOV, CI[conf, TOL]}
        { /ORIGIN | /NOORIGIN }
        /SAVE={PRED, RESID}
</code></pre><p><code>REGRESSION</code> 过程读取活动数据集，并输出与用户所指定线性模型相关的统计量。</p><p><code>VARIABLES</code> 子命令为必需，用于指定待分析的变量列表。关键字 <code>VARIABLES</code> 不可省略。<code>DEPENDENT</code> 子命令指定线性模型的因变量。<code>DEPENDENT</code> 子命令为必需。在 <code>VARIABLES</code> 子命令中列出但未在 <code>DEPENDENT</code> 子命令中列出的所有变量，均被视为线性模型中的解释变量。</p><p>所有其他子命令均为可选：</p><p><code>STATISTICS</code> 子命令指定要显示的统计量。接受以下关键字：</p><p><code>ALL</code></p><p>下列所有统计量。</p><p><code>R</code></p><p>模型导致的平方和与因变量总平方和之比。</p><p><code>COEFF</code></p><p>包含估计模型系数及其标准误的表格。</p><p><code>CI (conf)</code></p><p>此项仅当同时选定 COEFF 时才有意义。它指定应打印系数的置信区间。可选值 conf 必须置于括号内，是以百分比表示的期望置信水平。</p><p><code>ANOVA</code></p><p>模型的方差分析表。</p><p><code>BCOV</code></p><p>估计模型系数的协方差矩阵。</p><p><code>TOL</code></p><p>方差膨胀因子及其倒数。除非同时给定 COEFF，否则无效。</p><p><code>DEFAULT</code></p><p>等同于选定了 R、COEFF 和 ANOVA。这是未指定 /STATISTICS 命令，或指定了但未带任何参数时的结果。</p><p><code>ORIGIN</code> 与 <code>NOORIGIN</code> 子命令互斥。<code>ORIGIN</code> 表示回归应经过原点。当且仅当有理由相信回归确实经过原点——即上文的 <em>b_0</em> 为零时，才应使用此选项。默认为 <code>NOORIGIN</code>。</p><p><code>SAVE</code> 子命令使 PSPP 将拟合模型的残差或预测值保存到活动数据集。若此类变量不存在，PSPP 将残差存入名为 ‘RES1’ 的变量；若 ‘RES1’ 已存在，则存入 ‘RES2’；若 ‘RES1’ 和 ‘RES2’ 均已存在，则存入 ‘RES3’，依此类推。它对预测值变量名的选取方式类似，但以前缀 ‘PRED’ 命名。使用 <code>SAVE</code> 时，PSPP 会忽略 <code>TEMPORARY</code>，将临时变换视为永久变换。</p>`,24)])])}const _=o(a,[["render",E]]);export{A as __pageData,_ as default};
